import json, sys
d = json.load(open(sys.argv[1]))
ml = d.get("media_list") if isinstance(d.get("media_list"), dict) else {}
columns = d.get("columns") or ml.get("columns") or []
rows = d.get("rows") or ml.get("rows") or []
print(f"top_keys={sorted(d.keys())}")
print(f"row_count={len(rows)}")
print(f"col_count={len(columns)}")
col_id_to_name = {}
for c in columns:
    if isinstance(c, dict):
        cid = c.get("id") or c.get("column_id")
        cname = c.get("name")
        col_id_to_name[cid] = cname
print("columns:")
for cid, cname in col_id_to_name.items():
    print(f"  - {cname} ({cid})")
print("")
for i, row in enumerate(rows):
    if not isinstance(row, dict):
        continue
    rid = row.get("row_id") or row.get("id") or f"row_{i}"
    values = row.get("values") if isinstance(row.get("values"), dict) else {}
    print(f"--- row {i} | row_id={rid}")
    for cid, cname in col_id_to_name.items():
        cell = values.get(cid)
        if not isinstance(cell, dict):
            print(f"   {cname}: <null/non-dict>")
            continue
        display = cell.get("display")
        data = cell.get("data")
        if isinstance(display, str) and len(display) > 160:
            display = display[:160] + "..."
        if cname and ("article" in cname.lower() or "url" in cname.lower()):
            if isinstance(data, dict):
                title = data.get("title")
                url = data.get("url") or data.get("link")
                author = data.get("author")
                pub = data.get("source") or data.get("publication")
                date = data.get("date") or data.get("published_at")
                print(f"   {cname}: title={title!r} url={url} author={author!r} pub={pub!r} date={date!r}")
            else:
                print(f"   {cname}: display={display!r}")
        else:
            print(f"   {cname}: {display!r}")

