input.content:
import json, sys
d = json.load(open(sys.argv[1]))
result = d.get("result") if isinstance(d.get("result"), dict) else {}
research = result.get("research") if isinstance(result.get("research"), (dict, list)) else d.get("research") or []
if isinstance(research, list):
    for i, r in enumerate(research):
        if not isinstance(r, dict):
            continue
        print(f"--- research item {i}")
        for k in ("source_url","url","article_url","title","article_title","publication","outlet","author","authors","date","published_at","beat","beats","recent_articles","fit","fit_status","why","rationale","summary","notes"):
            v = r.get(k)
            if v is not None:
                if isinstance(v, str) and len(v) > 240:
                    v = v[:240]+"..."
                print(f"   {k}: {v!r}")
        nested_j = r.get("journalists")
        if isinstance(nested_j, list):
            print(f"   nested journalists: {len(nested_j)}")
            for j in nested_j:
                if isinstance(j, dict):
                    print(f"      - {j.get('name')} | {j.get('outlet') if not isinstance(j.get('outlet'),dict) else j.get('outlet').get('name')} | email={j.get('email')}")
elif isinstance(research, dict):
    print(f"research dict keys: {sorted(research.keys())}")

